               (DMA2D_REGULAR_ALPHA << 20) |
               (DMA2D_RB_REGULAR << 21) |
               (0xFFU << 24) |
               (DMA2D_CSS_422 << 18);

    regMask = DMA2D_BGPFCCR_CM | DMA2D_BGPFCCR_AM | DMA2D_BGPFCCR_ALPHA | DMA2D_BGPFCCR_AI | DMA2D_BGPFCCR_RBS | DMA2D_FGPFCCR_CSS;

