            // YUV422格式每个像素2字节，但按32位访问所以除以2
            uint32_t* src_block = pSrc + (block_y * xsize + block_x) / 2;
            uint32_t* dst_block = pDst + (block_y * xsize + block_x) / 2;

            // 计算输入行偏移（跳过当前块之外的像素）
